// lib/wire-tool-risk.js — GENERATED by scripts/refresh-wire-tool-surface.mjs.
// Do not hand-edit: rerun the script against the wire-ops-mcp / wire-build-mcp
// checkouts. Source of truth = each repo's tool-surface.json `tool_risk`.
// (add-wire-line-board, design D2)

// Every tool the two wire operation servers declare, with its risk and
// hosting server — a faithful mirror of the sources' `tool_risk`, `read`
// included. The gated subset below (risk !== read) is the pack publish
// lint's write-tool blocklist.
export const WIRE_TOOL_RISK = Object.freeze({
  wire_action_propose: Object.freeze({ risk: "write", server: "wire-ops-mcp" }),
  wire_artifact_archive: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_artifact_dashboard_create: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_artifact_doc_create: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_artifact_form_create: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_artifact_publish: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_artifact_record_view_create: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_artifact_restore: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_artifact_update: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_dataset_correct: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_dataset_correction_revert: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_dataset_create: Object.freeze({ risk: "write", server: "wire-build-mcp" }),
  wire_demand_submit: Object.freeze({ risk: "write", server: "wire-ops-mcp" }),
  wire_market_subscribe: Object.freeze({ risk: "cost", server: "wire-ops-mcp" }),
  wire_market_unsubscribe: Object.freeze({ risk: "write", server: "wire-ops-mcp" }),
  wire_pack_subscribe: Object.freeze({ risk: "write", server: "wire-ops-mcp" }),
  wire_pack_unsubscribe: Object.freeze({ risk: "write", server: "wire-ops-mcp" }),
  wire_self_action_list: Object.freeze({ risk: "read", server: "wire-ops-mcp" }),
  wire_self_action_propose: Object.freeze({ risk: "write", server: "wire-ops-mcp" }),
  wire_self_action_status: Object.freeze({ risk: "read", server: "wire-ops-mcp" }),
});

// paas action id → tool name (1:1 carriers only; mirrors fd-wire ACTION_TO_TOOL_NAME + wire.dataset.create).
export const WIRE_ACTION_TOOLS = Object.freeze({
  "wire.demand.submit": "wire_demand_submit",
  "wire.market.subscribe": "wire_market_subscribe",
  "wire.market.unsubscribe": "wire_market_unsubscribe",
  "wire.pack.subscribe": "wire_pack_subscribe",
  "wire.pack.unsubscribe": "wire_pack_unsubscribe",
  "wire.dataset.create": "wire_dataset_create",
  "wire.artifact.publish": "wire_artifact_publish",
  "wire.artifact.archive": "wire_artifact_archive",
  "wire.dataset.correct": "wire_dataset_correct",
  "wire.dataset.correction.revert": "wire_dataset_correction_revert",
});

// The gated universe: every declared tool whose risk is not `read`.
// Read stays outside the gate (its tier is auto), so mirroring those names
// here would be a real defect, not bookkeeping: a pack that declares a
// read-only tool is a read face, and isWireWriteTool() on that name would
// refuse it outright.
export const WIRE_WRITE_TOOLS = Object.freeze(
  Object.keys(WIRE_TOOL_RISK).filter((tool) => WIRE_TOOL_RISK[tool].risk !== "read").sort(),
);

export function riskForTool(tool) {
  return WIRE_TOOL_RISK[tool]?.risk ?? null;
}

export function serverForTool(tool) {
  return WIRE_TOOL_RISK[tool]?.server ?? null;
}

export function toolForAction(actionId) {
  return WIRE_ACTION_TOOLS[actionId] ?? null;
}

export function isWireWriteTool(tool) {
  const risk = WIRE_TOOL_RISK[tool]?.risk;
  return Boolean(risk) && risk !== "read";
}

